//! Byte-for-byte replay of `reference/vectors/11-12/fib_ligerito_test.json`
//! (generated by `reference/gen_vectors_11_12.py`): the vk encoding and
//! digest are reproduced from the vector's vk inputs, the instance
//! encoding round-trips, and the stored proof bytes decode and
//! re-encode identically. Producing the proof itself needs the prover
//! crate, which does not exist yet.
//!
//! The `ProofShape` is derived here exactly as Python's
//! `keygen.Derived`/`Derived.instance(T)` derive it, from the
//! `om-circuit`, `om-isa` and `om-mosaic` crates.

use std::collections::BTreeMap;
use std::path::PathBuf;

use om_elf::Params;
use om_format::{
    PcsMode, PcsProfile, ProofShape, REG_A, REG_D, VerifyingKey, choose_ad, decode_instance,
    decode_proof, decode_vk, encode_instance, encode_proof, encode_vk, pcs_free_k_count,
};
use om_spartan::SegmentKind;
use om_transcript::Hasher;
use serde_json::Value;

fn hex(s: &str) -> Vec<u8> {
    assert!(s.len().is_multiple_of(2), "odd hex");
    (0..s.len() / 2)
        .map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).expect("hex digit"))
        .collect()
}

fn bit_length(x: usize) -> usize {
    if x == 0 {
        0
    } else {
        (usize::BITS - x.leading_zeros()) as usize
    }
}

/// `(shape, components)` for this vk and `T`, replicating
/// `keygen.Derived` + `Derived.instance(T)` for the numbers
/// `proof_format.decode_proof` reads.
fn derive_shape(vk: &VerifyingKey, t: u64) -> (ProofShape, usize) {
    let cpu = om_circuit::Params {
        ram_log_words: vk.abi.ram_log_words,
        log_cycles: 2,
    };
    let segments = om_circuit::layout(&cpu);
    let nu = bit_length(2 * om_circuit::num_w_cols(&cpu)) - 1;
    let rho = bit_length(
        om_circuit::build_s1(&cpu)
            .len()
            .max(om_circuit::build_s2(&cpu).len())
            - 1,
    );
    let rom_len = om_isa::bytecode::expand(&vk.code, vk.entry_pc).rom.len();
    let (rom_a, rom_d) = choose_ad(2.max(bit_length(rom_len - 1)));
    let (ram_a, ram_d) = vk.ram_ad();

    let n = t.trailing_zeros() as usize;
    let s = n - 2;
    let mut comps: Vec<(i64, usize)> = Vec::new();
    let mut next_id = segments.len() as i64;
    let mut aux = |log_size: usize| {
        comps.push((next_id, log_size));
        next_id += 1;
    };
    for _ in 0..3 * REG_D {
        aux(REG_A / REG_D + n); // twist/reg/{ra0,ra1,wa}/i
    }
    aux(6 + n); // twist/reg/inc
    for _ in 0..ram_d {
        aux(ram_a / ram_d + n); // twist/ram/ra0/i
    }
    aux(6 + n); // twist/ram/inc
    for _ in 0..rom_d {
        aux(rom_a / rom_d + n); // shout/bytecode/ra/i
    }
    let mut all: Vec<(i64, usize)> = segments
        .iter()
        .enumerate()
        .filter(|(_, sg)| sg.kind == SegmentKind::Direct)
        .map(|(i, sg)| (i as i64, sg.log_size + s))
        .collect();
    all.extend(comps);
    let layout = om_mosaic::compute_layout(&all, 8);
    (
        ProofShape {
            rho,
            nu,
            num_segments: segments.len(),
            rom_a,
            rom_d,
            ell: layout.ell,
        },
        layout.placements.len(),
    )
}

#[test]
fn fib_ligerito_test_vector() {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../reference/vectors/11-12/fib_ligerito_test.json");
    let v: Value = serde_json::from_str(&std::fs::read_to_string(&path).expect("vector file"))
        .expect("vector json");

    let code: BTreeMap<u64, u32> = v["program"]["code"]
        .as_object()
        .expect("code")
        .iter()
        .map(|(k, w)| {
            (
                u64::from_str_radix(k, 16).expect("pc hex"),
                u32::from_str_radix(w.as_str().expect("word"), 16).expect("word hex"),
            )
        })
        .collect();
    let entry_pc = u64::from_str_radix(v["program"]["entry_pc"].as_str().expect("entry"), 16)
        .expect("entry hex");
    let vk = VerifyingKey::new(
        Params {
            ram_log_words: v["abi"]["A"].as_u64().expect("A") as u32,
            input_log_words: v["abi"]["I"].as_u64().expect("I") as u32,
            output_log_words: v["abi"]["O"].as_u64().expect("O") as u32,
            max_code_words: v["abi"]["max_code"].as_u64().expect("max_code"),
            hash_profile: Hasher::Sha256,
        },
        code,
        entry_pc,
        BTreeMap::new(),
        PcsMode::Ligerito,
        PcsProfile::Test,
        v["pcs"]["r"].as_u64().expect("r") as u8,
        v["pcs"]["t"].as_u64().expect("t") as u32,
    )
    .expect("vk");

    // vk bytes and digest reproduced from the vector's vk inputs.
    let vk_hex = hex(v["vk_hex"].as_str().expect("vk_hex"));
    assert_eq!(encode_vk(&vk), vk_hex);
    assert_eq!(
        vk.digest(),
        hex(v["vk_digest"].as_str().expect("vk_digest"))
    );
    assert_eq!(decode_vk(&vk_hex).expect("decode vk"), vk);

    // Instance bytes.
    let inst_hex = hex(v["instance_hex"].as_str().expect("instance_hex"));
    let inst = decode_instance(&inst_hex).expect("decode instance");
    let t = v["T"].as_u64().expect("T");
    assert_eq!(inst.t, t);
    assert_eq!(inst.exit_code, v["exit_code"].as_u64().expect("exit_code"));
    assert_eq!(inst.output, hex(v["output_hex"].as_str().expect("output")));
    assert!(inst.input.is_empty());
    assert_eq!(encode_instance(&inst), inst_hex);

    // Derived shape matches the vector's ell / component count.
    let (shape, components) = derive_shape(&vk, t);
    assert_eq!(shape.ell, v["ell"].as_u64().expect("ell") as usize);
    assert_eq!(
        components,
        v["components"].as_u64().expect("components") as usize
    );

    // Stored proof bytes decode and re-encode byte-for-byte.
    let proof_hex = hex(v["proof_hex"].as_str().expect("proof_hex"));
    assert_eq!(
        proof_hex.len(),
        v["proof_bytes"].as_u64().expect("proof_bytes") as usize
    );
    let proof = decode_proof(&vk, &proof_hex, t, &shape).expect("decode proof");
    assert_eq!(encode_proof(&vk, &proof), proof_hex);

    // Exact size model (spec 12.5: 12 454 of the 15 630 bytes are
    // outside the PCS opening for this vector).
    let (ram_a, ram_d) = vk.ram_ad();
    let k = pcs_free_k_count(
        t.trailing_zeros() as usize,
        ram_a,
        ram_d,
        shape.rom_a,
        shape.rom_d,
        shape.ell,
        shape.num_segments,
        shape.rho,
        shape.nu,
        REG_D,
    );
    assert_eq!(4 + 2 + 32 + 16 * k, 12_454);
}
